"""Prepare an unfitted four-state decoder and group-isolated head partitions."""
from pathlib import Path
import hashlib,json,shutil
import numpy as np
import torch
from joint_decoder import JointDecoder
R=Path(__file__).resolve().parents[1];S=R/'data/gas-head-candidate';D=R/'data/joint-decoder-candidate'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 preflight=json.loads((R/'results/joint-decoder-preflight.json').read_text());assert preflight['passed'] and preflight['decoder_sha256']==sha(R/'model_evaluation/joint_decoder.py');a=np.load(S/'features.npz');oldplan=json.loads((S/'candidate-plan.json').read_text());oldtrain=np.array(oldplan['train_indices']);confirmation=oldplan['validation_indices'];config=a['configuration'];unique=np.unique(config[oldtrain]);ranked=sorted(unique.tolist(),key=lambda c:hashlib.sha256(f'joint-decoder-v1:{c}'.encode()).digest());selection_configs=set(ranked[:len(ranked)//5]);selection=[int(i) for i in oldtrain if int(config[i]) in selection_configs];fit=[int(i) for i in oldtrain if int(config[i]) not in selection_configs]
 assert set(fit)|set(selection)==set(oldtrain) and not set(fit)&set(selection);assert not (set(config[fit])&set(config[selection]) or set(config[fit])&set(config[confirmation]) or set(config[selection])&set(config[confirmation]))
 D.mkdir(exist_ok=True)
 for name in ['features.npz','base-normalization.json']:shutil.copyfile(S/name,D/name)
 old=torch.load(S/'initial-head.pt',map_location='cpu',weights_only=False);norm=json.loads((S/'base-normalization.json').read_text());torch.manual_seed(3620);m=JointDecoder(old['feature_mean'],old['feature_std'],torch.tensor(norm['std']),torch.tensor(norm['physical_encoding_scales']),'direct');torch.save(dict(model=m.state_dict(),feature_mean=old['feature_mean'],feature_std=old['feature_std'],seed=3620),D/'initial-decoder.pt');shutil.copyfile(R/'model_evaluation/joint_decoder.py',D/'joint_decoder.py')
 plan=dict(status='prepared_not_fitted',modes=['direct','interval'],base_checkpoint_sha256=oldplan['base_checkpoint_sha256'],features=oldplan['features'],forecast_feature_status='Full-origin0 features here; all75 rolling16 origins prepared separately in data/joint-rolling-features and required for displayed-curve training/evaluation.',seed=3620,parameters_per_mode=sum(p.numel() for p in m.parameters()),fit_indices=fit,selection_indices=selection,confirmation_indices=confirmation,partition_counts={name:dict(histories=len(ids),configurations=len(np.unique(config[ids]))) for name,ids in [('fit',fit),('selection',selection),('confirmation',confirmation)]},partition_rule='Sort former TRAIN configuration IDs by SHA256(joint-decoder-v1:ID); first floor(config_count/5) form decoder-selection, remainder decoder-fit; retain all replicas together. Former validation is decoder-confirmation. Original test absent.',partition_limitation='Frozen GRU was previously trained on both decoder-fit and decoder-selection, and fixed feature/state normalization uses former TRAIN. Selection is therefore head-level transfer selection, not an end-to-end independent GRU holdout. Confirmation excludes GRU/head training and current head checkpoint selection, but its outcomes were examined in earlier development experiments and are not pristine. The base GRU checkpoint was itself selected on this former validation set; this is not an untouched complete-pipeline holdout.',baseline_definition='Direct zero head is exactly original GRU. Interval zero head projects masses and clips negative gas; it is NOT identical and must be evaluated as a separate untrained candidate. Original-GRU fallback bypasses decoder and is distinct from interval epoch0.',feedback='All corrected outputs remain output-only. Frozen GRU trajectories/hidden features still drive future base steps; corrected states are not fed back.',scope='Untrained all-four-output candidate. Interval mass-loss rates are separate from endpoint gas; no exact coarse trapezoid gas/fuel equality imposed. Small negative water labels and negative observed initial water are projected to nonnegative mass for interval decoding and cannot be represented exactly; heating-index negatives are allowed. No accuracy claim, optimizer update, test features or launch.',physical_scope=oldplan['physical_scope'])
 (D/'candidate-plan.json').write_text(json.dumps(plan,indent=2)+'\n');proof=dict(prepared=True,submitted=False,optimizer_updates=0,test_features_included=False,partition_counts=plan['partition_counts'],files={p.name:dict(sha256=sha(p),bytes=p.stat().st_size) for p in D.iterdir() if p.is_file()},scope=plan['scope']);(R/'results/joint-decoder-candidate-prepared.json').write_text(json.dumps(proof,indent=2)+'\n');print(json.dumps({k:v for k,v in plan.items() if not k.endswith('_indices')},indent=2))
if __name__=='__main__':main()
